ALTER TABLE nc_lifecycle_policy ADD COLUMN proration_policy TEXT CHECK(proration_policy IN ('invoice_now','next_invoice','none'));
CREATE TABLE nc_plan_changes(id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),item_id TEXT NOT NULL REFERENCES nc_items(id),new_item_id TEXT NOT NULL,new_price_id TEXT NOT NULL REFERENCES nc_prices(id),new_quantity INTEGER NOT NULL,effective_date TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('immediate','period_end')),policy TEXT NOT NULL CHECK(policy IN ('invoice_now','next_invoice','none')),policy_revision INTEGER NOT NULL,subscription_revision TEXT NOT NULL,source_invoice_id TEXT NOT NULL REFERENCES nc_invoices(id),quote_json TEXT NOT NULL,basis TEXT NOT NULL,prepared_by TEXT NOT NULL,prepared_name TEXT NOT NULL,prepared_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),decided_by TEXT,decided_at INTEGER,invoice_id TEXT REFERENCES nc_invoices(id),credit_id TEXT REFERENCES nc_credit_notes(id));
ALTER TABLE nc_credit_notes ADD COLUMN plan_change_id TEXT REFERENCES nc_plan_changes(id);
CREATE TABLE nc_plan_change_credit_requests(request_id TEXT PRIMARY KEY REFERENCES nc_credit_requests(id),change_id TEXT NOT NULL REFERENCES nc_plan_changes(id),invoice_id TEXT NOT NULL REFERENCES nc_invoices(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id));
CREATE TABLE nc_plan_change_adjustments(id TEXT PRIMARY KEY REFERENCES nc_plan_changes(id),subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),line_json TEXT NOT NULL,tax_cents INTEGER NOT NULL,invoice_id TEXT REFERENCES nc_invoices(id));
CREATE TRIGGER nc_plan_changes_generation_insert AFTER insert ON nc_plan_changes BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_plan_changes_generation_update AFTER update ON nc_plan_changes BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_plan_changes_generation_delete AFTER delete ON nc_plan_changes BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_plan_change_credit_requests_generation_insert AFTER insert ON nc_plan_change_credit_requests BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_plan_change_credit_requests_generation_update AFTER update ON nc_plan_change_credit_requests BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_plan_change_credit_requests_generation_delete AFTER delete ON nc_plan_change_credit_requests BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_plan_change_adjustments_generation_insert AFTER insert ON nc_plan_change_adjustments BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_plan_change_adjustments_generation_update AFTER update ON nc_plan_change_adjustments BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_plan_change_adjustments_generation_delete AFTER delete ON nc_plan_change_adjustments BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_plan_change_quote_immutable BEFORE UPDATE OF subscription_id,customer_id,item_id,new_item_id,new_price_id,new_quantity,effective_date,mode,policy,policy_revision,subscription_revision,source_invoice_id,quote_json,basis,prepared_by,prepared_name,prepared_at ON nc_plan_changes WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_plan_change_adjustment_immutable BEFORE UPDATE OF subscription_id,customer_id,line_json,tax_cents ON nc_plan_change_adjustments WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
